/*Table structure for table owner_room_record` */

DROP TABLE IF EXISTS `owner_room_record`;

CREATE TABLE `owner_room_record` (
  `record_id` bigint(20) NOT NULL COMMENT '房屋绑定记录id',
  `owner_room_id` varchar(32) DEFAULT NULL COMMENT '房屋绑定id',
  `community_id` bigint(20) DEFAULT NULL COMMENT '小区id',
  `building_id` bigint(20) DEFAULT NULL COMMENT '楼栋id',
  `unit_id` bigint(20) DEFAULT NULL COMMENT '单元id',
  `room_id` bigint(20) DEFAULT NULL COMMENT '房间id',
  `owner_id` bigint(20) DEFAULT NULL COMMENT '业主id',
  `owner_type` varchar(32) DEFAULT NULL COMMENT '业主类型',
  `room_status` varchar(32) DEFAULT NULL COMMENT '绑定状态（0审核中 1绑定 2审核失败,3解绑）',
  `record_audit_opinion` varchar(128) DEFAULT NULL COMMENT '审核意见',
  `record_audit_type` varchar(32) DEFAULT NULL COMMENT '审核人类型',
  `create_by_id` bigint(20) DEFAULT NULL COMMENT '创建人id',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`record_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='房屋绑定记录表 ';

